import { describe, it, expect } from "vitest";
import { formatGBP } from "./money";

describe("formatGBP", () => {
  it("formats pounds with two decimals", () => expect(formatGBP(1234.5)).toBe("£1,234.50"));
  it("handles zero", () => expect(formatGBP(0)).toBe("£0.00"));
  it("handles negatives", () => expect(formatGBP(-5)).toBe("-£5.00"));
  it("throws on NaN", () => expect(() => formatGBP(NaN)).toThrow());
});
```
For money, also mention: store amounts in minor units (pence) as integers to avoid floating point errors.

